def max_edges(n, altitudes):
    altitudes.sort()
    max_edges_count = 0

    for i in range(n):
        for j in range(i + 2, n):
            if altitudes[i] < altitudes[j] and altitudes[j] < altitudes[i + 1]:
                max_edges_count += 1

    return max_edges_count

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        altitudes = list(map(int, data[index + 1: index + 1 + n]))
        index += 1 + n
        results.append(max_edges(n, altitudes))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
